float MinDist (float2 uvi) 
{
   float tmp; float4 nb; float4 nb2; float2 pix;
   pix = texsize.zw*(1.0+length(uvi-0.5)*2.0);   
   nb.x = GetDist(uvi+pix*float2(-1,-1));   nb.y = GetDist(uvi+pix*float2(1,-1));
